<dialog id="auth"><button class="close" onclick="this.closest('dialog').close()">×</button><div class="eyebrow">JOIN THE ARTBID COMMUNITY</div><h2>Good art finds <em>its people.</em></h2><div class="auth-tabs"><button class="tab active" onclick="authMode('login',this)">Sign in</button><button class="tab" onclick="authMode('register',this)">Create account</button></div><?php if($reopenAuth&&$notice):?><div class="notice auth-notice"><?=e($notice)?></div><?php endif;?><form method="post" id="authform"><?=csrf_field()?><input type="hidden" name="action" value="login"><div class="name-field" hidden><label>Your name</label><input name="name" placeholder="How should we call you?"></div><label>Email address</label><input name="email" type="email" placeholder="you@example.com" required><label>Password</label><input name="password" type="password" placeholder="At least 8 characters" required><div class="role-field" hidden><label>I’m here as a</label><select name="role"><option>Buyer</option><option>Seller</option></select></div><button class="btn btn-dark full">Continue →</button></form></dialog>
<dialog id="create"><button class="close" onclick="this.closest('dialog').close()">×</button><div class="eyebrow">ADD TO THE COLLECTION</div><h2>List your <em>artwork.</em></h2><p class="form-intro">Share the details collectors need to discover and bid on your piece.</p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="create"><label for="art-title">Artwork title</label><input id="art-title" name="title" required maxlength="180" placeholder="A name that stays with you"><label for="art-description">Description</label><textarea id="art-description" name="description" required rows="4" placeholder="Describe the artwork, materials, and what makes it special"></textarea><label for="art-image">Artwork image URL <span class="optional">(optional)</span></label><input id="art-image" name="image_url" type="url" maxlength="1000" placeholder="https://example.com/image.jpg"><label for="art-category">Category</label><select id="art-category" name="category" required><option value="" disabled selected>Select a category</option><option>Abstract</option><option>Painting</option><option>Photography</option><option>Sculpture</option><option>Digital Art</option><option>Portrait</option></select><div class="two-fields"><div><label for="art-price">Starting price (₹)</label><input id="art-price" name="base_price" type="number" min="100" step="0.01" required placeholder="100"></div><div><label for="art-end">Auction ends</label><input id="art-end" name="ends_at" type="datetime-local" required></div></div><button class="btn btn-dark full">Publish auction →</button></form></dialog>
